#!/usr/bin/env python3
"""Genera el manual de producción sin ejecutar órdenes del servidor."""
import importlib.util, sys
from pathlib import Path
sys.dont_write_bytecode = True
ROOT=Path(__file__).resolve().parents[1]
spec=importlib.util.spec_from_file_location('render_orange',ROOT/'scripts/generar-manual-teams-orange.py')
m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
teams_chapters=m.chapters.copy();m.chapters.clear()
chapter,p,steps,note,code,table=m.chapter,m.p,m.steps,m.note,m.code,m.table
m.OUT=ROOT/'docs/archivo/manuales-hasta-20261111/produccion-20261110';m.STEM='Manual_pase_a_produccion_Portal_Orange'
chapter('Alcance, responsables y decisión inicial',
 p('Manual para añadir Portal Orange al campus de producción o actualizar una instalación Orange existente. Referencia: Moodle 4.5.1, local_orangeportal 2026111007, theme_orange 2026102900, base 9ea45bb más el configurador CLI de esta entrega. No incluye actualización de PHP, Moodle ni MySQL.'),
 table(['Responsable','Trabajo'],[['Sistemas','Respaldo, copia de directorios, actualización de Moodle, permisos de archivos, PHP CLI, cron y conectividad HTTPS.'],['Administrador general de Moodle','Categorías raíz, cohorte Orange, tema por cohorte, ajustes del portal, roles y Teams.'],['Administrador Orange','Cuentas y colectivos dentro de Orange; verificación de contenido y seguimiento.'],['Formación','Carga o revisión de documentos, cursos, actividades, destinatarios y publicación.'],['Responsable de Power Automate','URL de producción, conexiones, destino Teams e historial del flujo.']]),
 steps('Identificar si producción no tiene todavía Orange o ya contiene categorías, usuarios y publicaciones Orange.',
 'Si es una primera instalación, seguir todos los capítulos y escoger una única vía para la estructura: importación por consola o creación manual desde Moodle.',
 'Si Orange ya tiene datos, actualizar el código y conservar los datos existentes. No ejecutar el importador inicial ni recrear raíces, cohortes o roles que ya existan.',
 'Confirmar con el cliente qué estructura, contenidos y perfiles se han validado en pre antes de promoverlos.'),
 note('Copiar directorios de código no copia categorías, cursos, documentos, usuarios ni lecturas. Los IDs de pre no se reutilizan como IDs de producción. No se copia la base de datos de pre sobre el campus de producción.'))
chapter('Entregables y directorios que se deben cargar',
 table(['Entrega o carpeta','Destino y uso'],[['orangeportal-2026111007.zip','Descomprimir la carpeta orangeportal en local/orangeportal/ de Moodle. Contiene código y migraciones.'],['orange-2026102900.zip','Descomprimir la carpeta orange en theme/orange/. Necesario en primera instalación o si el tema está desactualizado.'],['Moove existente o distribución aprobada','Dependencia theme/moove/. Orange requiere theme_moove >= 2024100700. Referencia disponible: Moove 4.5.1, 2024100801. Si el campus tiene una versión posterior, no sobrescribirla ni degradarla; validar el tema hijo con esa versión.'],['catalogos-orange.json','Estructura inicial de categorías de Biblioteca y Formaciones, categorías de Incidencias/Comunicados, estados e impactos. No contiene documentos ni usuarios.'],['Inventario_estructura_Orange.csv','Lista de rutas de las categorías del JSON, para revisión y alternativa manual.'],['roles/*.xml y matriz','Seis roles no creados por el instalador y permisos de referencia. Se importan o comparan desde Moodle; no son asignaciones a personas.'],['Plantilla_agentes_Orange.csv','Cabeceras de referencia para cargar agentes desde Orange. Rellenar con datos reales y contraseñas individuales por el procedimiento del campus.'],['Comandos_pase_produccion_Orange.txt','Órdenes de referencia en texto, con marcadores que deben sustituirse antes de ejecutar.']]),
 code('RAIZ_MOODLE/\n  local/orangeportal/version.php\n  theme/orange/version.php\n  theme/moove/version.php'),
 note('RAIZ_MOODLE significa la carpeta que contiene config.php. /var/www/moodle se utiliza como ejemplo en este manual. No deben quedar carpetas duplicadas, como local/orangeportal/orangeportal/.'),
 p('El JSON que acompaña este manual es la referencia del 22 de octubre de 2026 disponible en el proyecto, no una exportación automática del estado actual de pre. Antes de cargarlo, comparar su inventario con lo aprobado y recoger las diferencias. El ZIP antiguo codigo-orange.zip de octubre no debe utilizarse para instalar el código de esta entrega.'),
 p('No cargar todo el repositorio, .env, config.php de otro entorno, moodledata de pre, contraseñas de demo, scripts de prueba ni las carpetas Postman como contenido web. Los cli/check_* incluidos en el plugin son pruebas locales, no órdenes del pase a producción.'))
chapter('Preparación del servidor y respaldo',
 steps('Anotar dominio del campus de producción, raíz Moodle, moodledata, usuario de servicio, versión de PHP CLI y mecanismo de cron existente.',
 'Inventariar versiones del plugin y de Orange/Moove; guardar la configuración del tema general y la portada del campus.',
 'Realizar un respaldo consistente de base de datos, código y moodledata mediante el procedimiento de Sistemas. Anotar ubicación y método de restauración.',
 'Guardar las configuraciones Orange existentes, IDs de raíces, cohorte base, catálogos y roles si ya existe Orange.',
 'Confirmar la ventana de despliegue y el estado del cron: coordinar el procesamiento de tareas durante mantenimiento para que no use archivos parcialmente copiados.',
 'Confirmar URL y destino de Teams de producción. Las pruebas y cargas no deben usar accidentalmente un flujo de otro ambiente.'),
 p('Sistemas identifica PHP en el entorno que ejecuta Moodle, con el usuario de servicio correspondiente:'),
 code('command -v php'),
 note('Los ejemplos siguientes usan php para facilitar la lectura. Si el servidor necesita una ruta absoluta, utilizar la devuelta por Sistemas. No se instala ni cambia la versión de PHP como parte de este pase.'))
chapter('Instalar el código: consola o interfaz de Moodle',
 p('Vía A, consola y copia de archivos: desde la raíz real de Moodle, con el usuario de servicio del campus:'),
 code('cd /var/www/moodle\nphp admin/cli/maintenance.php --enable'),
 steps('Sistemas copia los directorios de esta entrega en local/orangeportal y theme/orange. Moove solo se instala si falta o según la versión aprobada.',
 'Conservar propietario y permisos habituales del servidor; el usuario de PHP debe poder leer el código.',
 'Ejecutar la actualización y limpiar cachés. Revisar la salida antes de continuar.'),
 code('php admin/cli/upgrade.php --non-interactive\nphp admin/cli/purge_caches.php'),
 p('Vía B, instalador web: si el alojamiento y la política del campus permiten instalar complementos por la web:'),
 steps('Entrar como administrador general. En Servidor → Modo de mantenimiento, habilitar mantenimiento durante la intervención.',
 'Usar Administración del sitio → Plugins → Instalar plugins para cargar cada ZIP del componente, solo si esa función está habilitada y el servidor tiene los permisos necesarios.',
 'Si falta Moove, instalar primero la distribución aprobada de Moove, después local_orangeportal y después theme_orange. Si Moove ya existe, revisar compatibilidad antes de tocarlo.',
 'Seguir Administración del sitio → Notificaciones hasta completar todas las actualizaciones y guardar los ajustes nuevos que Moodle solicite.',
 'Purgar cachés desde Desarrollo → Purgar todas las cachés.'),
 note('Si la instalación web está deshabilitada o no permite reemplazar un componente existente, Sistemas debe copiar los directorios. No hay que desinstalar el plugin para actualizarlo: desinstalar puede eliminar sus datos.'),
 p('El instalador crea o actualiza las tablas y permisos propios. La revisión 2026111006 no añade tablas respecto a 2026111005; una instalación más antigua sí puede ejecutar migraciones previas.'),
 p('Al terminar la actualización del código, retirar mantenimiento para continuar las verificaciones funcionales, si el procedimiento de publicación del campus lo permite. Mantener Orange sin usuarios finales hasta validar su configuración:'),
 code('php admin/cli/maintenance.php --disable'),
 p('Alternativa web: desactivar mantenimiento en Servidor → Modo de mantenimiento. Si falla la actualización, conservar mantenimiento y resolver o restaurar el respaldo antes de abrir el campus.'))
chapter('Configuración automática: sin alternar consola y portal',
 p('Desde 2026111007 se puede completar la configuración inicial desde un archivo privado. Los capítulos posteriores de configuración web se conservan como alternativa y referencia de comprobación; no hay que intercalarlos en esta vía.'),
 steps('Copiar el código actualizado y ejecutar la actualización de Moodle.',
 'Preparar configuracion-orange.json a partir de la plantilla entregada, fuera del directorio web y con permisos restringidos. Completar site_url con la URL exacta del campus y php_cli con la ruta comprobada por Sistemas.',
 'Para una instalación nueva, utilizar las definiciones de raíces y cohorte con Número ID y create=true. El script las resuelve o crea y configura sus IDs sin buscarlos en la interfaz.',
 'Para una actualización existente, conservar los IDs o Números ID actuales y dejar catalog_file en null. No crear otra estructura ni activar allow_scope_change por rutina.',
 'Si es una primera carga aprobada, poner catalog_file a la ruta privada del JSON. Se importa dentro de la misma operación y repetir el mismo archivo no duplica el catálogo.',
 'Guardar la URL completa de Teams en un archivo privado y referirlo con teams.url_file. Si se va a activar, definir teams.enabled como true. Si se omite el archivo, se conserva la URL existente; la plantilla inicia Teams desactivado.',
 'Si procede, indicar en administrators los nombres de usuario ya existentes que deben ser administradores Orange. El script añade audiencia y rol restringido sin crear cuentas ni cambiar contraseñas.',
 'Ejecutar validación y después --apply. Leer la salida, que oculta la credencial. Purgar cachés.',
 'Sistemas verifica o configura cron cada minuto dentro del mismo pase. No se necesita la interfaz Moodle para programarlo. El configurador no ejecuta cron ni envía mensajes.'),
 code('php admin/cli/upgrade.php --non-interactive\nphp local/orangeportal/cli/configure.php --file=/ruta/privada/configuracion-orange.json\nphp local/orangeportal/cli/configure.php --file=/ruta/privada/configuracion-orange.json --apply\nphp admin/cli/purge_caches.php'),
 table(['Ajuste del archivo','Resultado'],[['portal.library / training / audience','Raíces y cohorte por ID existente o Número ID; creación explícita si faltan.'],['php_cli','Ruta hacia PHP CLI de Moodle.'],['theme','Habilitar temas de cohortes y aplicar Orange solo a la audiencia elegida, conservando el tema general.'],['teams','URL leída de archivo privado, activación, tipos y acciones.'],['catalog_file','Catálogo inicial aprobado; no es una sincronización de datos existentes.'],['administrators','Administradores Orange a partir de cuentas activas existentes.'],['allow_scope_change','Declaración explícita para un cambio revisado de raíces/audiencia previamente configuradas.']]),
 note('El script ejecuta las sincronizaciones de ámbito y permisos que necesita Orange, además de guardar variables. Repetirlo no duplica recursos. Una discrepancia con site_url, config.php, recursos o un catálogo existente se rechaza antes de aplicar.'),
 p('No crea cuentas, no importa todos los perfiles XML ni carga documentos/cursos. Estas cargas siguen su procedimiento específico. La comprobación funcional final se realiza desde el portal después de terminar la configuración por consola.'))
chapter('Crear o identificar las raíces de Biblioteca y Formaciones',
 steps('Abrir Administración del sitio → Cursos → Administrar cursos y categorías.',
 'Si es una primera instalación, crear una categoría raíz Biblioteca Orange y otra Formaciones Orange, en un ámbito exclusivo del proyecto. El nombre visible puede adaptarse; Orange no es obligatorio en el nombre.',
 'Si se utilizará el importador JSON, establecer Número ID de Biblioteca a orange_pre_library y Número ID de Formaciones a orange_pre_training.',
 'Abrir cada categoría y anotar su ID numérico en la URL. No confundirlo con Número ID, que es un texto técnico.',
 'Si ya existe Orange, identificar sus raíces actuales y conservarlas. No crear categorías paralelas ni mover contenidos de otros proyectos.'),
 table(['Dato','Valor en producción'],[['ID numérico de Biblioteca','________________'],['ID numérico de Formaciones','________________'],['Número ID técnico para importar Biblioteca','orange_pre_library'],['Número ID técnico para importar Formaciones','orange_pre_training']]),
 note('Aunque incluyan pre en su texto, esos dos Números ID son literales exigidos por el importador actual, también en producción. No sustituirlos por orange_pro_*. Son identificadores técnicos y no cambian el ambiente ni el nombre visible.'),
 p('Las raíces deben estar vacías para importar. Si se elige la carga manual del capítulo 7, estos Números ID específicos no son necesarios.'))
chapter('Cargar la estructura por consola: solo primera instalación',
 p('Si se ha usado configure.php con catalog_file, esta carga ya está hecha y no se debe repetir. Esta vía utiliza el JSON de referencia. No se combina con crear previamente las mismas subcategorías o catálogos a mano.'),
 steps('Sistemas guarda catalogos-orange.json fuera del directorio público, en una carpeta legible por el usuario de servicio.',
 'Confirmar raíces vacías y Números ID correctos. Confirmar que no existen categorías/publicaciones de Incidencias o Comunicados ni catálogos de estados/impactos guardados.',
 'Sustituir /ruta/privada/catalogos-orange.json, ID_BIBLIOTECA e ID_FORMACIONES en el comando. No ejecutar los marcadores literalmente ni copiar los IDs de pre.',
 'Ejecutar primero sin --apply: valida y no escribe.',
 'Revisar el resumen con el inventario aprobado. Si coincide, ejecutar el mismo comando con --apply.',
 'Limpiar cachés y comprobar las categorías desde Moodle.'),
 code('php local/orangeportal/cli/import_preproduction.php --file=/ruta/privada/catalogos-orange.json --library-root-id=ID_BIBLIOTECA --training-root-id=ID_FORMACIONES'),
 code('php local/orangeportal/cli/import_preproduction.php --file=/ruta/privada/catalogos-orange.json --library-root-id=ID_BIBLIOTECA --training-root-id=ID_FORMACIONES --apply\nphp admin/cli/purge_caches.php'),
 table(['Referencia del JSON entregado','Resultado esperado'],[['Biblioteca','167 subcategorías; 168 categorías contando su raíz. Incluye RPV y CENTREX.'],['Formaciones','Formación inicial y Formación continua: dos subcategorías, además de la raíz.'],['Incidencias','Cinco categorías con su jerarquía: Red móvil y Sistemas → Centrex → Alta → Sin Terminal.'],['Comunicados','Una categoría: Comunicado.'],['Estados e impactos','Se cargan nombres, códigos y activación del JSON; revisar el capítulo 8.']]),
 note('El script se llama import_preproduction.php por su origen, pero trabaja sobre la instalación que lo ejecuta. No crea cuentas, documentos, cursos, matrículas, ajustes del portal ni temas. Rechaza una segunda carga o datos existentes. No borrar contenido para forzar su ejecución.'),
 p('Desde el portal no hay una pantalla para subir este JSON. La alternativa sin consola para la estructura es crear manualmente las categorías y revisar los catálogos como se explica a continuación.'))
chapter('Cargar la estructura desde Moodle: alternativa manual',
 steps('Usar esta vía si no se va a ejecutar la importación inicial por consola. Mantener las dos raíces separadas de otros proyectos.',
 'En Cursos → Administrar cursos y categorías, seleccionar Biblioteca y crear sus subcategorías con Añadir categoría.',
 'Utilizar Inventario_estructura_Orange.csv como lista de comprobación. Crear primero los padres y después sus hijos; seleccionar explícitamente Categoría padre en cada alta.',
 'Reproducir el árbol aprobado, no solo los nombres. El orden de las filas del inventario permite crear padres antes que hijos. Comprobar el orden visible y ajustarlo desde la gestión de categorías si hace falta.',
 'En Formaciones crear Formación inicial y Formación continua debajo de su raíz.',
 'Después de configurar y acceder al portal, usar Administración Orange → Gestionar categorías para crear las categorías de Incidencias y Comunicados en sus secciones correctas.',
 'Revisar los estados e impactos desde Estados e impactos. Si se utilizó el JSON, no volver a crear estos mismos elementos.'),
 note('En este contexto, los directorios de Biblioteca y Formaciones son categorías de Moodle almacenadas en la base de datos. No son carpetas del servidor que se creen con mkdir. Copiar local/orangeportal y theme/orange no construye ese árbol.'),
 p('La referencia entregada contiene CENTREX como nodo inicial, sin inventar procesos debajo. Si el árbol aprobado en pre difiere del archivo de octubre, documentar y aplicar la diferencia antes de la apertura.'))
chapter('Revisar estados, impactos y prioridad crítica',
 table(['Catálogo de referencia','Revisión necesaria'],[['open / Abierta','Estado activo y no clasificado como cerrado.'],['progress / En seguimiento','El JSON de octubre lo contiene inactivo. El responsable decide si debe activarse antes de abrir producción.'],['closed / Cerrada','Estado activo, clasificado como cierre. Conservar el código y su clasificación.'],['normal, high, critical','Normal, Alto y Crítico activos en el JSON. El código critical activa el comportamiento crítico del portal.'],['Bajo','Impacto adicional del JSON con código propio; confirmar si se mantiene.']]),
 steps('Entrar con el administrador Orange o un perfil con local/orangeportal:manageoptions.',
 'Abrir Estados e impactos y revisar cada tipo por separado.',
 'Editar nombres y activación según lo aprobado. Para Crítico, editar la opción de código critical existente en lugar de crear otra con el mismo nombre.',
 'Comprobar que queda al menos un estado activo no cerrado y los impactos necesarios para publicar.',
 'Registrar la configuración final como parte de la entrega.'),
 p('En una instalación nueva sin JSON se muestran los valores predeterminados del plugin. La presencia de un nombre en pantalla no demuestra que coincida con el catálogo aprobado; revisar códigos, activación y cierre.'))
chapter('Cohorte Orange, tema y configuración del portal',
 steps('Mantener el tema corporativo y la portada general del campus. No seleccionar Orange como tema predeterminado global.',
 'En Usuarios → Cuentas → Cohortes, crear una cohorte de sistema Usuarios Orange, o identificar la existente. Puede usarse Número ID orange_portal_users.',
 'En Apariencia → Temas → Ajustes de temas, habilitar Permitir temas de cohortes. Revisar primero si hay otras cohortes con temas guardados que puedan activarse con este ajuste.',
 'Editar la cohorte Usuarios Orange y seleccionar Orange en su campo de tema forzado.',
 'En Administración del sitio → Portal Orange → Configuración Orange, seleccionar la cohorte de audiencia y escribir los IDs numéricos de Biblioteca y Formaciones de producción.',
 'Elegir Biblioteca como sección de entrada si esa es la opción aprobada. Revisar alertas automáticas de formación, que son independientes del envío de Teams.',
 'Activar el portal y guardar desde esa página para ejecutar sus validaciones y sincronizaciones. Evitar cambiar raíces/audiencia con SQL o copiar config_plugins de otro ambiente.',
 'En Apariencia → Temas → Orange revisar logo y personalizaciones aprobadas. Cerrar sesión y entrar con una cuenta Orange y otra ajena para comprobar el aislamiento.'),
 code('/admin/settings.php?section=local_orangeportal'),
 note('La pertenencia a Usuarios Orange da acceso al entorno Orange; el rol determina qué se puede hacer. Cambiar el nombre o el prefijo de una cuenta no la convierte en Orange. Un usuario de varias cohortes con temas distintos requiere revisión de la prioridad de temas.'),
 p('No incorporar usuarios finales a la cohorte antes de completar la configuración y la validación del contenido. Si producción ya tenía Orange, conservar su cohorte y sus raíces salvo un cambio planificado.'))
chapter('Primer administrador Orange y perfiles de trabajo',
 steps('El administrador general crea o identifica una cuenta individual de administración Orange desde Usuarios → Cuentas. No reutilizar una cuenta administradora global para probar el aislamiento.',
 'Añadir la cuenta a Usuarios Orange. Con el portal y raíces configurados, asignarle Administrador de Orange desde Usuarios → Permisos → Asignar roles del sistema.',
 'No asignarle Administrador del sitio ni Gestor global. El plugin crea orange_administrador y aplica su rol de contenidos en las raíces Orange.',
 'Entrar con la cuenta y comprobar Usuarios Orange, Colectivos Orange, contenido e informes. La configuración general de Teams debe seguir reservada al administrador general.',
 'Para Formación, Coordinación y Calidad, importar o comparar las definiciones por nombre corto desde Usuarios → Permisos → Definir roles. Utilizar los XML y la matriz del paquete; no duplicar roles existentes.',
 'Asignar cada rol a la persona real de producción en el contexto indicado. Los XML no trasladan las asignaciones de pre.'),
 table(['Perfil / rol','Asignación y alcance'],[['Agente','Pertenencia a Usuarios Orange y matrículas Estudiante en sus formaciones. Sin gestión ni exportación de seguimiento.'],['Formador / orange_publicador','Rol del portal en Sistema: gestionar publicaciones, estados y seguimiento según definición. Creación de cursos/categorías solo en raíces Orange; edición nativa en sus cursos.'],['Coordinación / orange_seguimiento','Consulta del portal en Sistema, limitada a los colectivos de pertenencia. Sin publicar ni cambiar incidencias.'],['Calidad / orange_calidad','Consulta separada de Coordinación. No conceder notas por defecto.'],['Administrador / orange_administrador','Administración Orange en Sistema y contenidos en sus raíces mediante los roles técnicos del plugin. No administración general del campus.']]),
 p('Los seis XML de referencia a importar o revisar son orange_publicador, orange_seguimiento, orange_calidad, orange_consulta_formativa, orange_creadorcontenidos y orange_gestorcategorias. Los roles de creación y categorías se asignan solo en las raíces Orange. La edición de cursos existentes requiere el rol nativo autorizado en esos cursos; para cursos nuevos Moodle asigna al creador el rol configurado en el campus.'),
 note('orange_consulta_formativa contiene permisos para notas e intentos. Asignarlo solo a responsables autorizados y en categorías/cursos aprobados; no darlo automáticamente a Calidad. Los permisos se suman si una persona tiene varios roles.'),
 p('No importar encima de los roles técnicos creados por el instalador para resolver diferencias de nombres. Mantener los nombres cortos y revisar las definiciones. El rol orange_autorrecursos lo gestiona el plugin, no necesita copiar tablas ni asignarse a todos los usuarios.'))
chapter('Colectivos, centros y carga de usuarios',
 steps('En Colectivos Orange crear los grupos de destinatarios y centros aprobados, por ejemplo un colectivo por centro. Son cohortes Moodle; no hay subcohortes jerárquicas.',
 'En Usuarios Orange crear las cuentas nuevas o utilizar Importar agentes desde CSV. La importación Orange crea agentes, no formadores ni coordinadores.',
 'Preparar CSV UTF-8 con las cabeceras de la plantilla. El mínimo requerido es username, firstname, lastname, email y password; idnumber, cohorts y courses son opcionales.',
 'Revisar la ayuda del importador y seleccionar colectivos y cursos del ambiente de producción. Utilizar la previsualización antes de confirmar la carga.',
 'Para cuentas ya existentes del campus y roles privilegiados, usar la administración general de Moodle y añadir su pertenencia a Orange. No crear cuentas duplicadas para forzar una importación.',
 'Validar con una cuenta importada el primer acceso, cambio de contraseña, tema y cursos disponibles.'),
 code('username;firstname;lastname;email;password;idnumber;cohorts;courses'),
 p('Los identificadores de colectivos y cursos deben corresponder a producción. Para varias asignaciones o campos opcionales, seguir el formato que explica el icono de ayuda de la versión instalada; no copiar IDs de pre. La importación permite seleccionar varias formaciones existentes, no obliga a matricular una persona cada vez.'),
 note('Usar correos y mecanismos de entrega de credenciales aprobados para producción. Una dirección ficticia puede impedir recuperación de contraseña y comunicaciones. La pertenencia a destinatarios no sustituye una matrícula de curso.'))
chapter('Carga real de Biblioteca y Formaciones',
 table(['Elemento','Cómo se carga'],[['Árbol de categorías','JSON inicial por consola o creación manual de categorías desde Moodle.'],['Documento de Biblioteca','Desde Biblioteca → Nuevo documento, seleccionar categoría y usar el selector visual nativo de actividades/recursos.'],['Curso o formación','Desde Formaciones → Crear formación; después preparar contenido, secciones, actividades, destinatarios y participantes.'],['Contenido aprobado en otro ambiente','Recrearlo desde los formularios o restaurar una copia nativa .mbz aprobada, con revisión de destinatarios y publicación.'],['Incidencia o comunicado','Recrear datos, destinatarios y recursos desde Orange. El JSON de categorías no migra publicaciones ni su seguimiento.']]),
 steps('En Biblioteca elegir la categoría exacta de la matriz. Añadir Archivo, Página, URL, Área de texto y medios u otro recurso nativo. No subir archivos directamente a moodledata.',
 'Revisar Usuarios individuales, Colectivos Orange y Grupos de cursos Orange. Guardar inicialmente sin Visible para sus destinatarios y sin Avisar por Teams.',
 'En Formaciones crear los cursos debajo de Formación inicial o Formación continua. Preparar sus secciones o colecciones y añadir recursos y actividades.',
 'Matricular a los usuarios existentes o utilizar sincronización de cohorte autorizada. Para una nueva edición, copiar el curso sin trasladar resultados de alumnos de la edición anterior.',
 'Si se usa .mbz, hacer copia desde el curso origen y restaurar en la categoría de producción correcta, sin usuarios de prueba ni sus intentos/notas. Mantener el curso destino oculto mientras se revisa.',
 'Después de restaurar, abrir Editar en cada formación y documento: comprobar destinatarios, matrículas, visibilidad, disponibilidad nativa, grupos y vínculos. La copia nativa no garantiza trasladar las reglas personalizadas, referencias e histórico de Orange.',
 'Probar documentos embebidos, archivos, URLs externas, cuestionarios y calificaciones con un agente autorizado antes de publicar.'),
 note('Las copias .mbz y el JSON de catálogos no son una migración completa de lecturas, incidencias, comunicados o trazabilidad del plugin. Conservar un histórico existente entre ambientes requiere un procedimiento específico aprobado; no sustituir por copiar tablas o toda la base de datos sobre producción.'),
 p('No marcar Teams en cada documento de una carga inicial salvo que se quiera realmente avisar por cada uno. Los cursos deben empezar ocultos durante la preparación; al copiar una edición nativa revisar la opción Ocultar.'))
# Reuse the verified Teams operational chapters, keeping this manual wholly server-oriented.
for title in ['Configurar la ruta de PHP CLI','Configurar el servicio de Teams desde Moodle','Comprobar el cron: ejecución automática','Solicitar un aviso al publicar o editar','Revisar pendientes y ejecutar una tarea concreta','Leer los logs de solicitud y respuesta','Interpretar errores y tareas omitidas','Si Moodle acepta la llamada pero no aparece en Teams']:
    selected=next(ch for ch in teams_chapters if ch['title']==title)
    if title=='Comprobar el cron: ejecución automática':
        selected={'title':selected['title'],'blocks':selected['blocks']+[p('También puede ejecutarse una vez desde la raíz real de Moodle; este ejemplo usa /var/www/moodle:'),code('cd /var/www/moodle\nphp admin/cli/cron.php --keep-alive=0'),note('La ejecución puntual no sustituye la programación automática cada minuto.') ]}
    m.chapters.append(selected)
chapter('Validación del pase y apertura a usuarios',
 steps('Verificar versiones: local_orangeportal 2026111007 y theme_orange 2026102900, con Moove compatible y sin cambiar el tema general del campus.',
 'Comparar Biblioteca y Formaciones con el inventario aprobado. Revisar estados, impactos y categorías de publicaciones.',
 'Comprobar una cuenta ajena a Orange: conserva su tema y no puede abrir contenido Orange por enlace directo.',
 'Comprobar un agente Orange: solo contenido dirigido a él, sin edición ni cambio de estado de incidencias. Verificar sus matrículas y notas propias.',
 'Comprobar Formador, Coordinación, Calidad y administrador Orange con cuentas separadas. Validar lectura, escritura y seguimiento por colectivos, incluidas URLs y exportaciones.',
 'Comprobar PHP CLI guardado y cron programado cada minuto. No dar Teams por operativo mientras todas las tareas sigan pendientes.',
 'Con un mensaje de prueba autorizado, marcar Visible y Avisar por Teams, guardar, comprobar ejecución, HTTP y recepción en el destino de producción.',
 'Comprobar un guardado sin Teams marcado y un borrador: ninguno debe solicitar un aviso.',
 'Verificar el campus fuera de Orange, recibir conformidad del responsable y registrar fecha, revisión y personas que aceptan el pase.',
 'Incorporar los usuarios finales y publicar el contenido aprobado. Supervisar cola, logs y flujo tras la apertura.'),
 p('Si la validación se realiza fuera de mantenimiento, mantener el acceso Orange restringido a las cuentas de validación hasta su aprobación. Sistemas conserva el procedimiento de mantenimiento del campus; no reabrir una actualización fallida.'))
chapter('Errores del despliegue y reversión',
 table(['Problema','Acción'],[['No aparecen menús Orange','Revisar portal habilitado, cohorte base, pertenencia, raíces y tema por cohorte. Cerrar sesión y entrar de nuevo.'],['Se ve Biblioteca pero el tema no cambia','Revisar Permitir temas de cohortes y tema forzado de Usuarios Orange. No cambiar el tema general.'],['Moodle muestra una versión vieja','Comprobar version.php realmente copiado en la instalación que sirve el campus, sin carpetas anidadas. Ejecutar actualización y purga. En varios nodos revisar todos los códigos y cachés del servicio.'],['Importador: falta --file legible y los dos IDs','Revisar ruta privada y permisos del JSON, además de ambos argumentos con IDs reales. No ejecutar el script solo.'],['Raíz no vacía o sin Número ID requerido','Comprobar orange_pre_library / orange_pre_training y que las raíces estén vacías. Si ya hay datos, no forzar el importador: usar actualización/manual.'],['Catálogos o categorías ya configurados','El importador es solo inicial. Conservar lo existente y aplicar cambios desde la interfaz.'],['Guardar ajustes vuelve a upgradesettings.php','Completar los campos nuevos obligatorios de todos los plugins, no solo Orange. Revisar errores de validación. Los ajustes de Boost Union o LearnR deben revisarse como tales; no reinstalar Orange ni cambiar el tema global.'],['Error PHP al pegar una orden','Usar el archivo de comandos y órdenes php normales; evitar fragmentos php -r o heredoc pegados incompletos. Sustituir marcadores antes de ejecutar.'],['Teams pendiente o no llega','Seguir PHP CLI, cron, cola y logs; HTTP 202 no demuestra entrega final. Revisar también el flujo Power Automate.']]),
 steps('Si falla una migración, mantener o activar mantenimiento y registrar el error antes de cambiar más elementos.',
 'Sistemas aplica el plan de reversión del respaldo consistente. Si la base de datos cambió, restaurar solo el código puede no ser suficiente.',
 'Restaurar de forma coordinada código, base de datos y moodledata según el punto de respaldo y los cambios que se hayan producido desde entonces.',
 'Revisar cron y avisos pendientes tras una restauración para no reenviar mensajes ya aceptados por Teams. Un mensaje ya publicado en Teams no se retira al restaurar Moodle.',
 'Comprobar el campus corporativo y Orange antes de retirar mantenimiento.'),
 note('Purgar cachés no borra usuarios, categorías, configuración ni cambia el tema predeterminado. Desinstalar el plugin sí puede eliminar sus tablas; no usarlo para resolver una actualización fallida.'))
chapter('Acta de entrega: datos que deben quedar anotados',
 table(['Dato','Valor de producción'],[['Fecha / revisión desplegada','____________________________'],['URL del campus / raíz Moodle / moodledata','____________________________'],['Usuario de servicio / PHP CLI','____________________________'],['Versiones Moodle / Orange / Moove','____________________________'],['Respaldo y procedimiento de restauración','____________________________'],['IDs de Biblioteca / Formaciones / cohorte Orange','____________________________'],['Estructura JSON o inventario aprobado y diferencias','____________________________'],['Cuentas responsables y roles asignados','____________________________'],['Programación cron / ubicación de su salida','____________________________'],['Flujo y destino Teams; responsable','____________________________'],['ID de tarea y resultado de prueba final','____________________________'],['Conformidad de Sistemas / cliente / administración','____________________________']]),
 p('La URL firmada y las contraseñas se conservan en el mecanismo seguro del cliente, no en esta acta. El inventario de catálogos adjunto es del 22/10/2026 y requiere aprobación antes de usarlo para una primera carga.'),
 p('No se han ejecutado órdenes en producción ni enviado mensajes reales de Teams al preparar este manual.'))
if __name__=='__main__':
    m.build(title='Manual de pase a producción',scope='Servidores del campus · Consola y portal Moodle',manualversion='1.1',pluginversion='2026111007',reference='9ea45bb + configurador CLI',description='Instalación, categorías de Biblioteca y Formaciones, usuarios, permisos, contenidos, Teams, PHP CLI, cron y validación del pase.')
